15	/// On success, writes the entry through to the `entries` Hive box (`Box
16	/// <Map>`, keyed by id, raw `EntryDto.toJson()` — Design Notes) *before*
17	/// returning `right(...)`, same "persist then return" ordering
18	/// `AuthRepositoryImpl._authenticate` already uses for its own
19	/// post-success side effect.
20	class EntriesRepositoryImpl implements EntriesRepository {
21	  EntriesRepositoryImpl({
22	    required EntriesRemoteDataSource remoteDataSource,
23	    required Box<Map> entriesBox,
24	  }) : _remoteDataSource = remoteDataSource,
25	       _entriesBox = entriesBox;
26	
27	  final EntriesRemoteDataSource _remoteDataSource;
28	  final Box<Map> _entriesBox;
29	
30	  @override
31	  Future<Either<Failure, Entry>> create({
32	    required String content,
33	    required EntrySource source,
34	    int? mediaDurationSeconds,
35	  }) async {
36	    final result = await _remoteDataSource.create(
37	      content: content,
38	      source: source,
39	      mediaDurationSeconds: mediaDurationSeconds,
40	    );
41	    return result.match((failure) async => left(failure), (dto) async {
42	      // A thrown Hive/disk exception must never escape unmapped (RNF09) —
43	      // same rationale/fallback `AuthRepositoryImpl` already uses for its
44	      // own local-persistence step.
45	      try {
46	        await _entriesBox.put(dto.id, dto.toJson());
47	      } catch (error) {
48	        return left(Failure.malformedResponse(message: error.toString()));
49	      }
50	      return right(_toEntry(dto));
51	    });
52	  }
53	
54	  @override
55	  Future<Either<Failure, EntriesPage>> list({
56	    String? cursor,
57	    int limit = 20,
58	  }) async {
59	    final result = await _remoteDataSource.list(cursor: cursor, limit: limit);
60	    return result.match(
61	      (failure) async {
62	        // Boundaries/Design Notes: the Hive-cache fallback is scoped to
63	        // `cursor == null` (the first/fresh page) only — a paginated
64	        // continuation (`cursor != null`) that fails with
65	        // `networkOffline`/`networkTimeout` propagates as `Left` like any
66	        // other pagination failure instead, so `MeusRegistrosCubit`'s own
67	        // `loadMoreFailed`/retry path handles it uniformly rather than a
68	        // full unrelated cache dump silently replacing the in-progress
69	        // paginated list (and breaking its newest-first ordering).
70	        if (cursor == null &&
71	            (failure is NetworkOffline || failure is NetworkTimeout)) {
72	          return _offlineFallback();
73	        }
74	        return left(failure);
75	      },
76	      (page) async {
77	        try {
78	          await _entriesBox.putAll({
79	            for (final dto in page.items) dto.id: dto.toJson(),
80	          });
81	        } catch (error) {
82	          // Same RNF09 rationale as `create()`'s own Hive-write guard — a
83	          // thrown Hive/disk exception must never escape unmapped.
84	          return left(Failure.malformedResponse(message: error.toString()));
85	        }
86	        return right(
87	          EntriesPage(
88	            items: page.items.map(_toEntry).toList(),
89	            nextCursor: page.nextCursor,
90	          ),
91	        );
92	      },
93	    );
94	  }
95	
96	  @override
97	  Future<Either<Failure, Entry>> getById(String id) async {
98	    final result = await _remoteDataSource.get(id);
99	    return result.match(
100	      (failure) async {
101	        // Boundaries: scoped to networkOffline/networkTimeout specifically
102	        // — every other Failure (notFound included) propagates as Left,
103	        // unmapped, same convention `list()`'s own cursor-scoped fallback
104	        // above uses.
105	        if (failure is NetworkOffline || failure is NetworkTimeout) {
106	          return _cachedEntryOrOriginalFailure(id, failure);
107	        }
108	        return left(failure);
109	      },
110	      (dto) async {
111	        // Same RNF09 rationale as `create()`/`list()`'s own Hive-write
112	        // guards — a thrown Hive/disk exception must never escape
113	        // unmapped.
114	        try {
115	          await _entriesBox.put(dto.id, dto.toJson());
116	        } catch (error) {
117	          return left(Failure.malformedResponse(message: error.toString()));
118	        }
119	        return right(_toEntry(dto));
120	      },
121	    );
122	  }
123	
124	  /// [getById]'s own offline/timeout fallback (Boundaries): a cache hit
125	  /// returns `Right` from the cached `EntryDto`; a cache miss propagates
126	  /// [originalFailure] unchanged — "no synthesized not-found" — rather than
127	  /// inventing a [Failure.notFound] this repository never actually
128	  /// received from the backend. A corrupt cached entry (should never
129	  /// happen — every entry here was written by [create]/[list]/[getById]
130	  /// themselves) maps to `Left(malformedResponse)` rather than throwing
131	  /// (RNF09), same guard `_offlineFallback()`'s own malformed-cache check
132	  /// uses.
133	  Either<Failure, Entry> _cachedEntryOrOriginalFailure(
134	    String id,
135	    Failure originalFailure,
136	  ) {
137	    try {
138	      final cached = _entriesBox.get(id);
139	      if (cached == null) {
140	        return left(originalFailure);
141	      }
142	      return right(_toEntry(EntryDto.fromJson(Map<String, dynamic>.from(cached))));
143	    } catch (error) {
144	      return left(Failure.malformedResponse(message: error.toString()));
145	    }
146	  }
147	
148	  /// The offline/timeout fallback (Boundaries): a full `entries` Hive box
149	  /// dump, sorted `occurredAt` desc, always `nextCursor: null` — a cached
150	  /// dump has no further page to request. A corrupt cached entry (should
151	  /// never happen — every entry here was written by [create]/[list]
152	  /// themselves) maps to `Left(malformedResponse)` rather than throwing
153	  /// (RNF09), same guard `create()`'s own Hive write already has.
154	  Either<Failure, EntriesPage> _offlineFallback() {
155	    try {
156	      final entries =
157	          _entriesBox.values
158	              .map(
159	                (json) => _toEntry(
160	                  EntryDto.fromJson(Map<String, dynamic>.from(json)),
161	                ),
162	              )
163	              .toList()
164	            ..sort(
165	              (a, b) =>
166	                  DateTime.parse(b.occurredAt)
167	                      .compareTo(DateTime.parse(a.occurredAt)),
168	            );
169	      return right(EntriesPage(items: entries, nextCursor: null));
170	    } catch (error) {
171	      return left(Failure.malformedResponse(message: error.toString()));
172	    }
173	  }
174	
175	  Entry _toEntry(EntryDto dto) => Entry(
176	    id: dto.id,
177	    content: dto.content,
178	    source: dto.source,
179	    chatMessageId: dto.chatMessageId,
180	    occurredAt: dto.occurredAt,
181	    serverRevision: dto.serverRevision,
182	    createdAt: dto.createdAt,
183	    updatedAt: dto.updatedAt,
184	    mediaDurationSeconds: dto.mediaDurationSeconds,
185	  );
186	}
