1	// The constructor keeps public named params (`dio`, `urlBuilder`) distinct
2	// from the private fields they initialize, so an initializing formal
3	// (which would force the external name to match) isn't a clean fit here.
4	// ignore_for_file: prefer_initializing_formals
5	import 'package:dio/dio.dart';
6	import 'package:fpdart/fpdart.dart';
7	
8	import '../failure/failure.dart';
9	import '../session/session_expiry_notifier.dart';
10	import 'dio_error_code.dart';
11	import 'header_interceptor.dart';
12	import 'url_builder.dart';
13	
14	/// AD-2/AD-5 — the one network façade every repository's data source calls
15	/// through. Builds the real URL via `UrlBuilder`, sends the request through
16	/// `dio` (header + retry interceptors already attached in DI), and maps
17	/// every outcome — success or failure — to `Either<Failure, T>`; no
18	/// dio/native exception ever escapes unmapped (RNF09).
19	///
20	/// Story 1.5: also the one detection point for a mid-session `AUTH_EXPIRED`
21	/// — signals [SessionExpiryNotifier] when one is seen outside
22	/// `HeaderInterceptor.anonKeyOnlyFunctions`, so the boot-time `auth-refresh`
23	/// call (Story 1.4's `restoreSession()`) never triggers it.
24	///
25	/// Tests mock this interface directly (per the architecture spine's testing
26	/// convention), not a fake transport layer underneath it.
27	class ApiClient {
28	  ApiClient({
29	    required Dio dio,
30	    required UrlBuilder urlBuilder,
31	    required SessionExpiryNotifier sessionExpiryNotifier,
32	  })  : _dio = dio,
33	        _urlBuilder = urlBuilder,
34	        _sessionExpiryNotifier = sessionExpiryNotifier;
35	
36	  final Dio _dio;
37	  final UrlBuilder _urlBuilder;
38	  final SessionExpiryNotifier _sessionExpiryNotifier;
39	
40	  Future<Either<Failure, Map<String, dynamic>>> get(
41	    String function, {
42	    List<String> pathParams = const [],
43	    Map<String, dynamic>? queryParameters,
44	  }) =>
45	      _send(
46	        () => _dio.get<Map<String, dynamic>>(
47	          _urlBuilder.build(function, pathParams),
48	          queryParameters: queryParameters,
49	        ),
50	      );
51	
52	  Future<Either<Failure, Map<String, dynamic>>> post(
53	    String function, {
54	    List<String> pathParams = const [],
55	    Object? data,
56	  }) =>
57	      _send(
58	        () => _dio.post<Map<String, dynamic>>(
59	          _urlBuilder.build(function, pathParams),
60	          data: data,
61	        ),
62	      );
63	
64	  Future<Either<Failure, Map<String, dynamic>>> patch(
65	    String function, {
66	    List<String> pathParams = const [],
67	    Object? data,
68	  }) =>
69	      _send(
70	        () => _dio.patch<Map<String, dynamic>>(
71	          _urlBuilder.build(function, pathParams),
72	          data: data,
73	        ),
74	      );
75	
76	  Future<Either<Failure, Map<String, dynamic>>> delete(
77	    String function, {
78	    List<String> pathParams = const [],
79	    Object? data,
80	  }) =>
81	      _send(
82	        () => _dio.delete<Map<String, dynamic>>(
83	          _urlBuilder.build(function, pathParams),
84	          data: data,
85	        ),
86	      );
87	
88	  Future<Either<Failure, Map<String, dynamic>>> _send(
89	    Future<Response<Map<String, dynamic>>> Function() request,
90	  ) async {
91	    try {
92	      final response = await request();
93	      final data = response.data;
94	      if (data == null) {
95	        return left(
96	          const Failure.malformedResponse(message: 'Empty response body'),
97	        );
98	      }
99	      return right(data);
100	    } on DioException catch (e) {
101	      return left(_mapDioException(e));
102	    } catch (e) {
103	      return left(Failure.malformedResponse(message: e.toString()));
104	    }
105	  }
106	
107	  Failure _mapDioException(DioException e) {
108	    final code = dioErrorCodeOf(e);
109	    if (code == null) {
110	      // Covers a cancelled request and an HTTP response that doesn't carry
111	      // the expected `{code, message, retryable}` body — neither is one of
112	      // the 13 backend codes, so neither is retryable (dioErrorCodeOf).
113	      return Failure.malformedResponse(
114	        message: e.message ?? 'Malformed response',
115	      );
116	    }
117	    final data = e.response?.data;
118	    final message = data is Map ? data['message'] : null;
119	    final failure = Failure.fromCode(
120	      code,
121	      (message is String ? message : null) ?? e.message ?? 'Unknown error',
122	    );
123	    if (failure is AuthExpired && !_isAnonKeyOnlyCall(e)) {
124	      _sessionExpiryNotifier.notifyExpired();
125	    }
126	    return failure;
127	  }
128	
129	  /// Whether [e]'s request targeted one of the three `security: []`
130	  /// operations (signup, login, refresh) — the only calls `AUTH_EXPIRED`
131	  /// must never be treated as a mid-session expiry for, since those are the
132	  /// anon-keyed calls Story 1.4's `restoreSession()` itself makes.
133	  ///
134	  /// Mirrors `HeaderInterceptor.onRequest`'s own fail-open behavior: a
135	  /// malformed `requestOptions.path` (shouldn't happen — `UrlBuilder`
136	  /// always produces a valid URL) is treated as "not anon-key-only" rather
137	  /// than letting a `FormatException` escape this mapping step unmapped
138	  /// (RNF09).
139	  bool _isAnonKeyOnlyCall(DioException e) {
140	    String function;
141	    try {
142	      function = HeaderInterceptor.functionNameOf(e.requestOptions.path);
143	    } catch (_) {
144	      function = '';
145	    }
146	    return HeaderInterceptor.anonKeyOnlyFunctions.contains(function);
147	  }
148	}
